function drawHpBar(ctx, x, y, w, label, hp, maxHp, block, statuses) {
  text(ctx, label, x, y - 8, 13, '#e8e2d4', 'bold');
  roundRect(ctx, x, y, w, 20, 10);
  ctx.fillStyle = '#20242e';
  ctx.fill();
  const frac = Math.max(0, hp / maxHp);
  if (frac > 0) {
