  }
  text(ctx, `${hp} / ${maxHp}`, x + w + 10, y + 16, 14, '#fff', 'bold');
  // Badges sit to the right of the life text, never over the bar.
  let bx = x + w + 78;
  if (block > 0) {
    roundRect(ctx, bx, y - 2, 66, 24, 8);
    ctx.fillStyle = '#2f5f8f';
    ctx.fill();
    text(ctx, `Block ${block}`, bx + 8, y + 15, 13, '#cfe4ff', 'bold');
