}

function drawTable(ctx, view, game) {
  // Felt with a vignette and a gold inner border.
  const grad = ctx.createRadialGradient(640, 360, 120, 640, 360, 760);
  grad.addColorStop(0, '#2e6b52');
  grad.addColorStop(1, '#173d2d');
  ctx.fillStyle = grad;
